    return SuggestedActionListView(
      items: ((json['items'] as List?) ?? const [])
            .whereType<Map>()
            .map((item) => SuggestedAction.fromJson(item.cast<String, dynamic>()))
            .toList(growable: false),
    );
  }

  Map<String, dynamic> toJson() => <String, dynamic>{
        'items': items,
      };
}

